import React, { useEffect, useRef, useState } from 'react';
import { Alert, Button, Empty, Form, Input, Modal, Popconfirm, Select, Space, Table, Tooltip, Typography } from 'antd';
import { DeleteOutlined, PlusOutlined, ReloadOutlined, QuestionCircleOutlined } from '@ant-design/icons';

const base = '/api/console/applications/{application_id}/api-keys';


export default function ApplicationApiKeyTable({ ctx }) {
  const { t } = ctx.i18n;
  const locale = ctx.i18n.locale.replace("_", "-");
  const formatDate = value => value ? new Date(value).toLocaleString(locale, { timeZone: 'Asia/Shanghai', hour12: false }) : t('Never used');
  const [catalog, setCatalog] = useState(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [notice, setNotice] = useState(null);
  const [creating, setCreating] = useState(false);
  const [created, setCreated] = useState(null);
  const [form] = Form.useForm();
  const [sort, setSort] = useState({ sort_by: 'created_at', sort_order: 'desc' });
  const sortRef = useRef({ sort_by: 'created_at', sort_order: 'desc' });
  const [pagination, setPagination] = useState({ current: 1, pageSize: 10 });
  const revision = useRef(0);
  const action = useRef(false);

  async function refresh() {
    const request = ++revision.current;
    setLoading(true);
    try {
      const response = await ctx.api.get('/api/ex/application-api-key-table', { query: sortRef.current });
      if (request === revision.current) setCatalog(response.catalog);
    } catch (e) {
      if (request === revision.current) setNotice({ type: 'error', message: "Unable to load API keys: {{reason}}", values: { reason: e.message } });
    } finally { if (request === revision.current) setLoading(false); }
  }
  useEffect(() => { refresh(); return () => { revision.current++; }; }, []);

  function changeTable(nextPage, filters, sorter, extra) {
    if (extra.action === 'sort') {
      const next = { sort_by: sorter.field, sort_order: sorter.order === 'ascend' ? 'asc' : 'desc' };
      sortRef.current = next;
      setSort(next);
      setPagination({ current: 1, pageSize: nextPage.pageSize });
      refresh();
    } else {
      setPagination({ current: nextPage.current, pageSize: nextPage.pageSize });
    }
  }

  async function createKey() {
    if (action.current) return;
    let values;
    try { values = await form.validateFields(); } catch { return; }
    action.current = true; setBusy(true); setNotice(null);
    try {
      const key = await ctx.api.post(base, { path: { application_id: values.application_id }, body: { name: values.name.trim() } });
      setCreating(false);
      setCreated(key);
      form.resetFields();
      await refresh();
    } catch (e) { setNotice({ type: 'error', message: "Unable to create the key: {{reason}}", values: { reason: e.message } }); }
    finally { action.current = false; setBusy(false); }
  }

  async function deleteKey(record) {
    if (action.current) return;
    action.current = true; setBusy(true); setNotice(null);
    try {
      await ctx.api.delete(base + '/{key_id}', { path: { application_id: record.application_id, key_id: record.id } });
      setNotice({ type: 'success', message: "The API key has been deleted." });
      await refresh();
    } catch (e) { setNotice({ type: 'error', message: "Unable to delete the key: {{reason}}", values: { reason: e.message } }); }
    finally { action.current = false; setBusy(false); }
  }

  return <div style={{ padding: 24, minWidth: 0 }}>
    <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', justifyContent: 'space-between', gap: 16, marginBottom: 24 }}>
      <div>
        <Typography.Title level={4} style={{ margin: '0 0 8px' }}>{t("API keys")}</Typography.Title>
        <Typography.Text type="secondary">{catalog ? t("{{count}} keys created, grouped by application.", { values: { count: catalog.items.length } }) : t("Manage API keys by application.")}</Typography.Text>
      </div>
      <Space>
        <Button aria-label={t("Refresh API keys")} icon={<ReloadOutlined aria-hidden />} onClick={refresh} loading={loading} disabled={busy}>{t("Refresh")}</Button>
        <Button type="primary" icon={<PlusOutlined aria-hidden />} disabled={busy || loading || !catalog?.applications.length}
          onClick={() => { form.resetFields(); setNotice(null); setCreating(true); }}>{t("Create key")}</Button>
      </Space>
    </div>
    {notice && <Alert {...notice} message={t(notice.message, { values: notice.values })} showIcon closable onClose={() => setNotice(null)} style={{ marginBottom: 16 }} />}
    <Table aria-label={t("Application API keys")} rowKey="id" dataSource={catalog?.items || []} loading={loading} scroll={{ x: 1120 }}
      onChange={changeTable} sortDirections={['ascend', 'descend', 'ascend']}
      pagination={{ ...pagination, showSizeChanger: true, pageSizeOptions: [10, 20, 50] }}
      locale={{ emptyText: <Empty description={t("No API keys yet")} /> }} columns={[
        { title: t("Name"), dataIndex: 'name', width: 160, ellipsis: true },
        { title: t("Application groups"), dataIndex: 'application_name', width: 240, render: (name, record) => <Tooltip title={record.application_id}><Typography.Text style={{ display: 'inline-block', maxWidth: '100%', whiteSpace: 'normal', overflowWrap: 'anywhere' }}>{name}</Typography.Text></Tooltip> },
        { title: <Space size={6}>{t("Key")}<Tooltip title={t("Only the key prefix is shown. The full key is displayed once when created.")}><QuestionCircleOutlined aria-label={t("Key display information")} /></Tooltip></Space>, dataIndex: 'token_prefix', width: 190, render: prefix => <Typography.Text code>{prefix}****</Typography.Text> },
        { title: t("Created at"), dataIndex: 'created_at', width: 190, render: formatDate, sorter: true, sortOrder: sort.sort_by === 'created_at' ? (sort.sort_order === 'asc' ? 'ascend' : 'descend') : null },
        { title: t("Last used at"), dataIndex: 'last_used_at', width: 190, render: formatDate, sorter: true, sortOrder: sort.sort_by === 'last_used_at' ? (sort.sort_order === 'asc' ? 'ascend' : 'descend') : null },
        { title: t("Actions"), key: 'actions', width: 90, render: (_, record) => <Popconfirm title={t("Delete key \"{{name}}\"?", { values: { name: record.name } })} description={t("Application: {{name}}. This key will stop working immediately after deletion.", { values: { name: record.application_name } })} onConfirm={() => deleteKey(record)} okText={t("Delete")} cancelText={t("Cancel")} disabled={busy || loading}>
          <Button type="text" danger aria-label={t("Delete key {{name}}", { values: { name: record.name } })} icon={<DeleteOutlined aria-hidden />} disabled={busy || loading} />
        </Popconfirm> },
      ]} />
    {creating && <Modal title={t("Create API key")} open onOk={createKey} onCancel={() => setCreating(false)} okText={t("Create")} cancelText={t("Cancel")} confirmLoading={busy} closable={!busy} maskClosable={false} cancelButtonProps={{ disabled: busy }}>
      {notice?.type === 'error' && <Alert {...notice} message={t(notice.message, { values: notice.values })} showIcon style={{ marginBottom: 16 }} />}
      <Form form={form} layout="vertical" disabled={busy}>
        <Form.Item label={t("Application groups")} name="application_id" rules={[{ required: true, message: t("Please select an application") }]}>
          <Select aria-label={t("Application")} showSearch optionFilterProp="label" placeholder={t("Select an application")} options={catalog.applications.map(app => ({ value: app.id, label: app.name }))} />
        </Form.Item>
        <Form.Item label={t("Name")} name="name" rules={[{ required: true, whitespace: true, message: t("Please enter a key name") }]}><Input maxLength={100} placeholder={t("For example: development")} /></Form.Item>
      </Form>
    </Modal>}
    {created && <Modal title={t("Save API key")} open onCancel={() => setCreated(null)} maskClosable={false} footer={<Button type="primary" onClick={() => setCreated(null)}>{t("Done")}</Button>}>
      <Alert type="info" showIcon message={t("The full key is shown only once. Copy and store it safely. Only the prefix will be available after closing.")} style={{ marginBottom: 20 }} />
      <Typography.Paragraph copyable={{ text: created.token }} code style={{ overflowWrap: 'anywhere' }}>{created.token}</Typography.Paragraph>
    </Modal>}
  </div>;
}
